#!/bin/bash
set -e

# ==============================================================================
#  Amber V2 blog: rebuild times, upstream Crystal vs this fork
# ==============================================================================
#
#  Builds the blog in benchmarks/amber_blog (generated by
#  scripts/demo_amber_blog.sh) and times, from an empty cache: a cold build, a
#  build with nothing changed, then three edits, each checked on the running
#  server:
#
#    model       a method body (`Post#excerpt`)
#    controller  an action body (`PostController#index` adds a header)
#    template    the heading of `post/index.ecr`
#
#  Rows: upstream `crystal build`, the fork's `crystal build`, and the fork's
#  `crystal run --watch` (the everyday loop: the time from saving to the
#  server answering with the edit).
#
#  Usage:
#    STOCK_CRYSTAL=/path/to/upstream/bin/crystal ./scripts/benchmark_amber_blog.sh
#
#  CRYSTAL is the fork (default: `crystal` on PATH). Needs `shards`, `curl`
#  and `sqlite3`; port 3000 must be free.
#
# ==============================================================================

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
APP="${APP:-${REPO_ROOT}/benchmarks/amber_blog}"
NAME=$(basename "$APP")
CRYSTAL="${CRYSTAL:-crystal}"
if [ -z "$STOCK_CRYSTAL" ]; then
  echo "Set STOCK_CRYSTAL to an upstream Crystal compiler." >&2
  exit 1
fi

cd "$APP"
[ -d lib ] || shards install > /dev/null

# A fresh development database from the migrations' `Up` sections.
DB="db/${NAME}_development.db"
rm -f "$DB"
for f in db/migrations/*.sql; do
  awk '/^-- \+micrate Up/ { up = 1; next } /^-- \+micrate Down/ { up = 0 } up' "$f"
done | sqlite3 "$DB"

EDITED="src/models/post.cr src/controllers/post_controller.cr src/views/post/index.ecr"
WORK=$(mktemp -d)
for f in $EDITED; do mkdir -p "$WORK/orig/$(dirname "$f")" && cp "$f" "$WORK/orig/$f"; done
restore() { for f in $EDITED; do cp "$WORK/orig/$f" "$f"; done; }
watcher=
server=
cleanup() {
  restore
  [ -n "$server" ] && kill "$server" 2> /dev/null
  [ -n "$watcher" ] && kill -INT "$watcher" 2> /dev/null && wait "$watcher" 2> /dev/null
  rm -rf "$WORK"
}
trap cleanup EXIT

now() { date +%s%N; }
ms() { echo $(( ($2 - $1) / 1000000 )); }
URL=http://127.0.0.1:3000/posts

edit_model()      { sed -i 's/body\[0, length\] + "..."/body[0, length] + "…"/' src/models/post.cr; }
edit_controller() { sed -i '0,/    @posts = Post.all.to_a/s//    response.headers["X-Demo"] = "edited"\n    @posts = Post.all.to_a/' src/controllers/post_controller.cr; }
edit_template()   { sed -i 's|<h1>Posts</h1>|<h1>Posts (edited)</h1>|' src/views/post/index.ecr; }

# Waits until the server answers with $1 in the headers or body (60s at most).
wait_for() {
  for _ in $(seq 1200); do
    curl -s -i "$URL" 2> /dev/null | grep -q "$1" && return 0
    sleep 0.05
  done
  return 1
}

# Starts the built binary and checks it serves $1.
check() {
  "$1" > /dev/null 2>&1 &
  server=$!
  local result=PASS
  wait_for "$2" || result=FAIL
  kill $server; wait $server 2> /dev/null || true
  server=
  echo $result
}

# Row with `crystal build`: label, compiler.
bench_build() {
  local label=$1 cr=$2 out="$WORK/$NAME" s
  export CRYSTAL_CACHE_DIR="$WORK/cache-$label"
  build() { s=$(now); "$cr" build "src/$NAME.cr" -o "$out" > "$WORK/log" 2>&1 || { cat "$WORK/log" >&2; exit 1; }; ms $s $(now); }
  local cold noop model controller template c1 c2
  cold=$(build); noop=$(build)
  edit_model; model=$(build)
  edit_controller; controller=$(build); c1=$(check "$out" "X-Demo: edited")
  edit_template; template=$(build); c2=$(check "$out" "Posts (edited)")
  restore
  rm -rf "$CRYSTAL_CACHE_DIR"
  row "$label" $cold $noop $model $controller $template "$c1 $c2"
}

# Row with `crystal run --watch`: time from the edit to the server serving it.
bench_run() {
  local label=$1 cr=$2 s
  export CRYSTAL_CACHE_DIR="$WORK/cache-$label"
  s=$(now)
  "$cr" run --watch > "$WORK/run.log" 2>&1 &
  watcher=$!
  wait_for "<h1>Posts</h1>" || { cat "$WORK/run.log" >&2; exit 1; }
  local cold=$(ms $s $(now))
  edited() { s=$(now); "$cr" watch build > /dev/null 2>&1; wait_for "$1" && ms $s $(now) || echo FAIL; }
  local noop model controller template
  noop=$(edited "<h1>Posts</h1>")
  edit_model; model=$(edited "<h1>Posts</h1>")
  edit_controller; controller=$(edited "X-Demo: edited")
  edit_template; template=$(edited "Posts (edited)")
  local checks="PASS PASS"
  case "$controller $template" in *FAIL*) checks=FAIL ;; esac
  kill -INT $watcher; wait $watcher 2> /dev/null || true
  watcher=
  restore
  rm -rf "$CRYSTAL_CACHE_DIR"
  row "$label" $cold $noop $model $controller $template "$checks"
}

secs() { case $1 in *[!0-9]*) echo "$1" ;; *) awk "BEGIN { printf \"%.2f\", $1 / 1000 }" ;; esac; }
row() {
  printf "%-26s %8s %8s %8s %8s %8s   %s\n" "$1" $(secs $2) $(secs $3) $(secs $4) $(secs $5) $(secs $6) "$7"
}

echo "$NAME: $(find src -name '*.cr' -o -name '*.ecr' | wc -l | tr -d ' ') source files"
echo "upstream: $("$STOCK_CRYSTAL" --version | head -1)"
echo "fork:     $("$CRYSTAL" --version | head -1)"
echo
printf "%-26s %8s %8s %8s %8s %8s   %s\n" "seconds" cold nochange model ctrl template served
bench_build "upstream crystal build" "$STOCK_CRYSTAL"
bench_build "fork crystal build" "$CRYSTAL"
bench_run "fork crystal run (watch)" "$CRYSTAL"
